package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/gin-gonic/gin"
)

const baseDir = "/app/data/reports"

// ReportServer serves generated PDF reports to authenticated users
type ReportServer struct {
	router *gin.Engine
}

func NewReportServer() *ReportServer {
	s := &ReportServer{}
	s.router = gin.Default()
	s.setupRoutes()
	return s
}

func (s *ReportServer) setupRoutes() {
	api := s.router.Group("/api/v1")
	{
		api.GET("/reports/:category/*filename", s.getReport)
		api.GET("/health", s.healthCheck)
	}
}

// sanitizeInput performs basic input validation
func sanitizeInput(input string) string {
	// Remove null bytes
	input = strings.ReplaceAll(input, "\x00", "")
	// Remove leading slashes to prevent absolute paths
	input = strings.TrimLeft(input, "/")
	return input
}

func (s *ReportServer) getReport(c *gin.Context) {
	category := c.Param("category")
	filename := c.Param("filename")

	// Validate category - alphanumeric only
	for _, ch := range category {
		if !((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '-' || ch == '_') {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid category"})
			return
		}
	}

	// Sanitize filename
	filename = sanitizeInput(filename)

	// Build the full path
	fullPath := filepath.Join(baseDir, category, filename)

	// Security check: verify the resolved path is within baseDir
	// Note: filepath.Join does NOT resolve symlinks or normalize ".." fully
	if !strings.HasPrefix(fullPath, baseDir) {
		c.JSON(http.StatusForbidden, gin.H{"error": "access denied"})
		return
	}

	// Check file exists
	info, err := os.Stat(fullPath)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "report not found"})
		return
	}

	if info.IsDir() {
		c.JSON(http.StatusBadRequest, gin.H{"error": "cannot serve directory"})
		return
	}

	// Read and serve the file
	data, err := ioutil.ReadFile(fullPath)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to read report"})
		return
	}

	// Determine content type based on extension
	ext := filepath.Ext(filename)
	contentType := "application/octet-stream"
	switch ext {
	case ".pdf":
		contentType = "application/pdf"
	case ".csv":
		contentType = "text/csv"
	case ".json":
		contentType = "application/json"
	}

	c.Data(http.StatusOK, contentType, data)
}

func (s *ReportServer) healthCheck(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{"status": "ok"})
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	server := NewReportServer()
	fmt.Printf("Starting report server on :%s\n", port)
	server.router.Run(":" + port)
}
